@[simp] theorem positivePowerWord_prod {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i) (k : ℕ) :
    (positivePowerWord u hij k).prod = u.prod ^ (k + 1)

theorem positivePowerWord_prod_ne_one {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i) (k : ℕ) :
    u.prod ^ (k + 1) ≠ 1

theorem zpow_ne_one_of_cyclicallyReduced {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i)
    (k : ℤ) (hk : k ≠ 0) : u.prod ^ k ≠ 1

theorem inv_isAppend {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hu : IsAppend u) :
    IsAppend u.inv

@[simp] theorem positivePowerWord_head {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i) (n : ℕ) :
    (positivePowerWord u hij n).head = u.head

theorem positivePowerWord_isAppend {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i) (n : ℕ)
    (hu : IsAppend u) : IsAppend (positivePowerWord u hij n)

@[simp] theorem positivePowerWord_last {i j : LeftIndex}
    (u : CoprodI.NeWord (LeftFactor G) i j) (hij : j ≠ i) (n : ℕ) :
    (positivePowerWord u hij n).last = u.last

theorem oneTapeProgram_supports (c : ToPartrec.Code) :
    @TM1.Supports TapeSymbol OneTapeState (Option Symbol)
      (oneTapeStateInhabited c) oneTapeProgram (oneTapeSupport c)

theorem classify_step {Q : Type*} {M : Machine Q} {c d : Config Q}
    (hstep : step M c = some d) {w : List (Symbol Q)}
    (hrew : ThueStep (system M) (encode c) w) :
    w = encode d ∨ ∃ p, w = encode p ∧ step M p = some c

theorem rule_step {Q : Type*} {M : Machine Q}
    {x y : List (Symbol Q)} (hxy : Rule M x y) (l r : List (Symbol Q)) :
    ThueStep (system M) (l ++ x ++ r) (l ++ y ++ r)

theorem simulation_halt {Q : Type*} {M : Machine Q} {c : Config Q}
    (hc : step M c = none) :
    ThueEq (system M) (encode c) (target : List (Symbol Q))

theorem simulation_step {Q : Type*} {M : Machine Q} {c d : Config Q}
    (hcd : step M c = some d) :
    ThueStep (system M) (encode c) (encode d)

theorem target_undecidable {α β : Type*}
    [Primcodable α] [Primcodable β]
    {S : ThueSystem α} {T : ThueSystem β}
    (f : Embedding S T) (P : List α)
    (h : ¬ ComputablePred fun Q : List α => ThueEq S Q P) :
    ¬ ComputablePred fun Q : List β => ThueEq T Q (f.encode P)

theorem rho₂_forward (L M : List A₂) {X Y : List A₂}
    (h : ThueEq (stage₂System L M) X Y) :
    ThueEq (baseSystem (rho₂ L) (rho₂ M)) (rho₂ X) (rho₂ Y)

theorem rho₂_step (L M : List A₂) {X Y : List A₂}
    (h : ThueStep (stage₂System L M) X Y) :
    ThueEq (baseSystem (rho₂ L) (rho₂ M)) (rho₂ X) (rho₂ Y)

theorem columnsFrom_length {t width : ℕ}
    (rows : Fin t → List (Fin 2)) (start : ℕ) :
    (columnsFrom rows start width).length = width * t

theorem firstNormal_prefix_congr (l : List A₂) {X Y : List A₂}
    (h : firstNormal X = firstNormal Y) :
    firstNormal (l ++ X) = firstNormal (l ++ Y)

theorem stage₂Eq_eCount (L M : List A₂)
    (hLM : eCount L = eCount M) {X Y : List A₂}
    (h : ThueEq (stage₂System L M) X Y) : eCount X = eCount Y

theorem stage₂Step_eCount (L M : List A₂)
    (hLM : eCount L = eCount M) {X Y : List A₂}
    (h : ThueStep (stage₂System L M) X Y) : eCount X = eCount Y

theorem transpose_length {t width : ℕ}
    (rows : Fin t → List (Fin 2)) :
    (transpose width rows).length = width * t

theorem paddedTransposeLast_length {t width : ℕ}
    (rows : Fin t → List (Fin 2)) (j : Fin t) (z : Fin 2) :
    (paddedTransposeLast width rows j z).length = (width + 1) * t

theorem exists_liftBinary_of_eCount_zero {W : List A₂}
    (hW : eCount W = 0) :
    ∃ B : List (Fin 2), W = liftBinary B

theorem reflect (F E : Fin r → List (Fin n)) {X Y : List (Fin n)}
    (h : ThueEq (stage₁System F E) (encode F E X) (encode F E Y)) :
    ThueEq (finiteSystem F E) X Y

theorem simulate (F E : Fin r → List (Fin n)) {X Y : List (Fin n)}
    (h : ThueEq (finiteSystem F E) X Y) :
    ThueEq (stage₁System F E) (encode F E X) (encode F E Y)

theorem decode_step (F E : Fin r → List (Fin N))
    (hF : ∀ i, F i ≠ []) (hE : ∀ i, E i ≠ []) {X : List (Fin N)}
    {W : List (Fin 2)}
    (h : ThueStep (stage₂PrimeSystem F E) (rho₁ N X) W) :
    ∃ Y, W = rho₁ N Y ∧ ThueStep (finiteSystem F E) X Y

theorem decode_thueEq (F E : Fin r → List (Fin N))
    (hF : ∀ i, F i ≠ []) (hE : ∀ i, E i ≠ []) {X : List (Fin N)}
    {W : List (Fin 2)}
    (h : ThueEq (stage₂PrimeSystem F E) (rho₁ N X) W) :
    ∃ Y, W = rho₁ N Y ∧ ThueEq (finiteSystem F E) X Y

theorem noAAA_liftBinary {W : List (Fin 2)}
    (h : ¬ ∃ l r, W = l ++ [(0 : Fin 2), 0, 0] ++ r) :
    NoAAA (liftBinary W)

theorem swappedToHNN_mem_stageOne_of_mem_J_one {x : G0}
    (hx : x ∈ J 1) :
    swappedToHNN x ∈ MonoidHom.range g1ToG0HNN

theorem toHNN_mem_stageOne_of_mem_J_zero {x : G0}
    (hx : x ∈ J 0) :
    toHNN x ∈ MonoidHom.range g1ToG0HNN
